css:
.door-spec { font-size: 11px; }
.spec-header { display: flex; justify-content: space-between; align-items: baseline;
	border-bottom: 2px solid #1f272e; padding-bottom: 6px; margin-bottom: 12px; }
.spec-header h2 { margin: 0; font-size: 16px; letter-spacing: 0.04em; text-transform: uppercase; }
.spec-part { font-family: monospace; font-size: 13px; font-weight: 600; }
.spec-meta { width: 100%; margin-bottom: 14px; }
.spec-meta td { padding-right: 18px; vertical-align: top; }
.spec-meta span { display: block; font-size: 9px; text-transform: uppercase;
	letter-spacing: 0.06em; color: #8d99a6; }
.spec-lines { width: 100%; border-collapse: collapse; }
.spec-lines td { padding: 2px 0; border-bottom: 1px solid #f0f2f4; }
.spec-seq { width: 44px; color: #b8c0c8; font-family: monospace; font-size: 9px; }
.spec-desc { color: #4c5b68; }
.spec-value { text-align: right; font-weight: 600; white-space: nowrap; }
.spec-spacer td { border-bottom: none; height: 8px; }
.spec-footer { margin-top: 14px; padding-top: 6px; border-top: 1px solid #d1d8dd;
	font-size: 9px; color: #8d99a6; }
